send_cors_headers();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);if(rate_limit('influencer-register|'.request_ip(),6,3600))json_response(429,['success'=>false,'message'=>'Too many registration attempts.']);$body=get_json_body();$data=validate_fields($body,['full_name'=>'required|string|min:2|max:140','email'=>'required|email|max:190','phone'=>'required|mobile','password'=>'required|string','handle'=>'required|string|min:3|max:100','terms'=>'required|boolean']);if(!is_strong_enough_password($data['password']))json_response(422,['success'=>false,'message'=>'Use 12+ password characters with upper, lower, number and symbol.']);if(!filter_var($data['terms'],FILTER_VALIDATE_BOOL))json_response(422,['success'=>false,'message'=>'Accept the creator terms and disclosure policy.']);$email=strtolower($data['email']);$mobile=preg_replace('/\D+/','',$data['phone']);$handle=strtolower(trim($data['handle']));if(!preg_match('/^[a-z0-9._-]{3,100}$/',$handle))json_response(422,['success'=>false,'message'=>'Creator handle must be 3–100 letters, numbers, dots, hyphens or underscores.']);$db=get_db();$check=$db->prepare('SELECT id FROM influencers WHERE email=:email OR mobile=:mobile OR handle=:handle');$check->execute(['email'=>$email,'mobile'=>$mobile,'handle'=>$handle]);if($check->fetch())json_response(409,['success'=>false,'message'=>'An account already uses this email, phone or handle.']);$id=uuid_string();$otp=(string)random_int(100000,999999);$db->beginTransaction();try{$db->prepare('INSERT INTO influencers (id,full_name,email,mobile,password_hash,email_verified,otp_hash,otp_expires_at,otp_last_sent_at,handle,bio,platforms_json,status,verification_status,created_at) VALUES (:id,:name,:email,:mobile,:password,0,:otp,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 10 MINUTE),UTC_TIMESTAMP(),:handle,NULL,:platforms,"pending_verification","not_submitted",UTC_TIMESTAMP())')->execute(['id'=>$id,'name'=>$data['full_name'],'email'=>